def pancake_sort(lst):
    n = len(lst)
    for i in range(n-1, -1, -1):
        max_index = lst.index(max(lst[:i+1]))
        if max_index == i:
            continue
        if max_index != 0:
            lst = lst[:max_index+1] + lst[max_index:-1]
        lst = lst[:i+1] + lst[i+1:-1]
    return lst
