def ncr_modp(n, r, p):
    def factorial_modp(n, p):
        f = 1
        for i in range(1, n+1):
            f = (f * i) % p
        return f

    def inverse_modp(a, p):
        return pow(a, p-2, p)

    def ncr_modp(n, r, p):
        if r > n:
            return 0
        if r == 0:
            return 1
        numerator = (factorial_modp(n, p) * inverse_modp(factorial_modp(n-r, p), p) * inverse_modp(factorial_modp(r, p), p)) % p
        return numerator

    return ncr_modp(n, r, p)
[Done]

